    ["通关[肃风监正]玩法第一关"] = "ƱượǉǦảƾǦǉƽứǦǃƽấǉǦǁốƾǦƸƽơƾǦ[ǥƕƸǦƫƽǄǃƼǦƢƾƑǂǦƞƽƓǃƽ]",
    ["通关[常盛集热购]单人模式第一关"] = "ƱượǉǦảƾǦǉƽứǦǃƽấǉǦƸƽếǦđộǦđơǃǦ[ǥƽườǃƼǦǥƽịǃƽǦǥậǅǦƩƽƾệǉǦƞấǊ]",
    ["完成该区域的[礼让]玩法"] = "ƣǄƐǃǦǉƽƐǃƽǦǁốƾǦƸƽơƾǦ[ƧễǦƩƽượǃƼ]ǦƸủƶǦǀƽǊǦǋựƸǦǃƐǓ",
    ["通过话术[松下之辩]第一层考验"] = "ƱượǉǦǆǊƶǦǉầǃƼǦǉƽửǦǉƽƑƸƽǦǉƽứǦǃƽấǉǦƸủƶǦǥƽǄạƾǦǉƽǊậǉǦ[ǥƖǃƼǦƣạǦƞƽƾǦƝƾệǃ]",
    ["共游中"] = "ĐƶǃƼǦƸƖǃƼǦǤǊǦǃƼǄạǃ",
    ["寻探之友"] = "ǥầǂǦǥƽƑǂǦƞƽƾǦƣữǊ",
    ["助阵之友"] = "ǥǇợǦƞƽƾếǃǦƞƽƾǦƣữǊ",
    ["论道之友"] = "ƧǊậǃǦĐạǄǦƞƽƾǦƣữǊ",
    ["清河的水哟宽又长"] = "ƩướƸǦǥƽƶǃƽǦƣƐǦƇƾǦǇộǃƼǦǁạƾǦǤƐƾ",
    ["一篙子下去三尺浪"] = "ƨộǉǦǈƐǄǦƸắǂǦǍǊốǃƼǦǈƚǃƼǦƸƶǄǦƷƶǦǉƽướƸ",
    ["三尺浪来往东淌"] = "ƮƚǃƼǦƸƶǄǦƷƶǦǉƽướƸǦƸƽảǓǦǋềǦđƇǃƼ",
    ["船底擦着个沙石床"] = "ĐƑǓǦǉƽǊǓềǃǦƸọǦǈƑǉǦƷƃƾǦđƑǦƸƑǉ",
    ["抬头望见泰山高又大"] = "ƩƼẩǃƼǦđầǊǦǉǇƇǃƼǦǉƽấǓǦǥƽƑƾǦƮơǃǦƸƶǄǦǁạƾǦǁớǃ",
    ["低头瞧见篙子弯了样"] = "ƞƕƾǦđầǊǦǃƽƔǃǦǉƽấǓǦƸƁǓǦǈƐǄǦđƃǦƸǄǃƼǦǋƛǃƼ",
    ["篙子弯照样撑"] = "ƮƐǄǦƸǄǃƼǦǉƽƔǦǋẫǃǦƸứǦƸƽốǃƼ",
    ["歇了气力就对不住浪"] = "ƩƼƽỉǦǉƶǓǦǂấǉǦǈứƸǦǉƽƔǦƸƚǦǁỗƾǦǋớƾǦǈƚǃƼǦǍƇ",
    ["快来了吧？约好了这个时辰的....."] = "ƮắǅǦđếǃǦǇồƾǦƸƽứ?ǦĐƃǦƽẹǃǦƼƾờǦǃƐǓǦǂƐ.....",
    ["咋还没来......再不来赶不上了......"] = "ƮƶǄǦǋẫǃǦƸƽưƶǦǉớƾ......ǦƦƽƇǃƼǦǉớƾǦǃữƶǦǁƐǦǀƽƇǃƼǦǀịǅǦđƁǊ......",
    ["小刘说好这个点吧？怎么还没来？"] = "ǥƾểǊǦƧưǊǦƷảǄǦǁƐǦƼƾờǦǃƐǓǦđƕǃƼǦǀƽƇǃƼ?ǦƮƶǄǦǋẫǃǦƸƽưƶǦǉƽấǓǦđƁǊ?",
    ["哟，登山的？我们也是，我们仨在这等人呢。"] = "Ồ,ǦđƾǦǁƺǄǦǃƕƾǦƐ?ǦƞƽƕǃƼǦǉƶǦƸũǃƼǦǋậǓ,ǦƷƶǦǃƼườƾǦƸƽƕǃƼǦǉƶǦđƶǃƼǦđợƾǦǃƼườƾǦởǦđƁǓ.",
    ["是嘞，约好了这个点来夜爬的，结果小刘这"] = "ĐƕǃƼǦǋậǓ,ǦƽẹǃǦƼƾờǦǃƐǓǦǉớƾǦǁƺǄǦǃƕƾǦđƙǂ,ǦǀếǉǦǆǊảǦǁƐǦƸƑƾǦǉƽằǃƼǦǥƾểǊǦƧưǊǦǃƐǓ",
    ["小子不知道怎么回事，还没来，急死我们仨了。"] = "ƦƽƇǃƼǦƷƾếǉǦƸƚǦƸƽǊǓệǃǦƼƔǦǂƐǦƼƾờǦǋẫǃǦƸƽưƶǦǉớƾ,ǦǁƐǂǦƷƶǦƸƽƕǃƼǦǉƶǦǈốǉǦƸảǦǇǊộǉ.",
    ["这里都是准备夜间登山的人？"] = "ỞǦđƁǓǦđềǊǦǁƐǦǃƼườƾǦƸƽǊẩǃǦƷịǦǁƺǄǦǃƕƾǦđƙǂǦǈƶǄ?",
    ["基本上是吧！你到前头看看，那有家饺子馆，那准备登山的人更多嘞！"] = "ƞơǦƷảǃǦǁƐǦǋậǓ!ǦƣǊǓǃƽǦđƐƾǦǇƶǦǅƽƓƶǦǉǇướƸǦǂƐǦǍƺǂ,ǦƸƚǦǆǊƑǃǦǈủƾǦƸảǄǦǀƾƶǦǀƔƶ,ǦƸƽỗǦđƚǦǃƼườƾǦƸƽǊẩǃǦƷịǦǁƺǄǦǃƕƾǦƸƛǃǦđƇǃƼǦƽơǃǦǃƽƾềǊ!",
    ["对咯！哎哎，他好像来了！"] = "ĐƕǃƼǦǇồƾ!ǦƦƔƶǦǀƔƶ,ǦƽƔǃƽǦǃƽưǦƽắǃǦǉớƾǦǇồƾ!",
    ["好像看错了......"] = "ƣƔǃƽǦǃƽưǦǃƽƔǃǦǃƽầǂǦǇồƾ......",
    ["江兄，你怎么这个时候来？"] = "ƢƾƶǃƼǦƽǊǓǃƽ,ǦǈƶǄǦƽǊǓǃƽǦǁạƾǦǉớƾǦǋƐǄǦƼƾờǦǃƐǓ?",
    ["林不晚"] = "ƧƁǂǦƝấǉǦƱƃǃ",
    ["信上就说是这个时候。不曾想黑灯瞎火的，恐有魑魅魍魉。"] = "ǥǇǄǃƼǦǉƽưǦǃƚƾǦǁƐǦƼƾờǦǃƐǓǦǂƐ.ǦƦƽƇǃƼǦǃƼờǦǉốƾǦǄǂǦǃƽưǦǂựƸ,ǦƺǦǁƐǦƸƚǦǁũǦǈƾǦǂịǦǋƅǃƼǦǁượǃƼ.",
    ["江早"] = "ƢƾƶǃƼǦǥảǄ",
    ["林兄还说我，自己不也这时候来了？"] = "ƧƁǂǦƽǊǓǃƽǦƸƛǃǦǃƚƾǦđệ,ǦƸƽẳǃƼǦǅƽảƾǦƽǊǓǃƽǦƸũǃƼǦǉớƾǦǁƕƸǦǃƐǓǦǈƶǄ?",
    ["人齐了吗？是不是还差一个？"] = "ĐủǦǃƼườƾǦƸƽưƶ?ǦƞƚǦǅƽảƾǦƸƛǃǦǉƽƾếǊǦǂộǉǦǃƼườƾǦǀƽƇǃƼ?",
    ["来来来——就差你一个了！"] = "ǥớƾǦđƁǓǦǉớƾǦđƁǓǦ——ǦƸƽỉǦƸƛǃǦǉƽƾếǊǦǂỗƾǦǂƔǃƽǦǃƼươƾǦǉƽƇƾ!",
    ["话说百年之前，这儿曾有一神秘客栈。那日大雪，众多江湖人聚集于此——"] = "ƞƽǊǓệǃǦǀểǦǇằǃƼǦǉǇăǂǦǃăǂǦǉǇướƸ,ǦǃơƾǦǃƐǓǦǉừǃƼǦƸƚǦǂộǉǦǆǊƑǃǦǉǇọǦǉƽầǃǦƷƓ.ǦƩƼƐǓǦđƚǦǉǊǓếǉǦǁớǃ,ǦƷƶǄǦǀẻǦƼƾƶǃƼǦƽồǦǉụǦǉậǅǦǉạƾǦđƁǓǦ——",
    ["那夜里——血光漫天！忽然间，几百人皆命丧于此。"] = "ĐƙǂǦđƚǦ——ǦƽǊǓếǉǦǆǊƶǃƼǦǃƼậǅǦǉǇờƾ!ǦĐộǉǦǃƽƾƙǃ,ǦǂấǓǦǉǇăǂǦǃƼườƾǦđềǊǦǉƑǃƼǦǂạǃƼǦǉạƾǦƸƽốǃǦǃƐǓ.",
    ["杀的那是昏天黑地，血流成河！"] = "ƢƾếǉǦđếǃǦǉǇờƾǦđấǉǦǂƖǦǂịǉ,ǦǂƑǊǦƸƽảǓǦǉƽƐǃƽǦǈƇǃƼ!",
    ["这位大爷，你这是在说什么呢？"] = "ƱịǦđạƾǦƼƾƶǦǃƐǓ,ǦƇǃƼǦđƶǃƼǦǃƚƾǦƼƔǦǋậǓ?",
    ["哈哈，小娃娃，外头来的吧？大爷说的可是这儿百年前的事儿！"] = "ƣƶƽƶ,ǦǃƽƚƸǦƸǄǃ,ǦǉừǦǃƼǄƐƾǦđếǃǦǅƽảƾǦǀƽƇǃƼ?ǦƧƃǄǦƼƾƐǦǃƐǓǦđƶǃƼǦǃƚƾǦƸƽǊǓệǃǦƸủƶǦǉǇăǂǦǃăǂǦǉǇướƸǦởǦđƁǓǦđấǓ!",
    ["那之后呢？"] = "ƮƶǊǦđƚǦǉƽƔǦǈƶǄ?",
    ["之后？这儿就冤魂丛生，每到夜半，"] = "ƮƶǊǦđƚ?ǦƩơƾǦǃƐǓǦǄƶǃǦƽồǃǦǉụǦǉậǅ,ǦƸứǦǂỗƾǦđộǦǃửƶǦđƙǂ,",
    ["隐隐有女子啜泣，婴孩啼哭，还有索命之语！"] = "ƧạƾǦǉƽấǅǦǉƽǄƑǃƼǦǉƾếǃƼǦǃữǦǃƽƁǃǦǃứƸǦǃở,ǦǉǇẻǦǃƽỏǦǀƽƚƸǦǄƶǦǄƶ,ǦƸƛǃǦƸƚǦƸảǦǁờƾǦđƛƾǦǂạǃƼ!",
    ["要不是那文津馆出手，怕是现在也好不了！"] = "ƩếǊǦǀƽƇǃƼǦǃƽờǦƱăǃǦǥƁǃǦƬǊƑǃǦǇƶǦǉƶǓ,ǦƺǦǁƐǦƷƁǓǦƼƾờǦǋẫǃǦƸƽưƶǦǓƙǃǦổǃǦđượƸǦđƁǊ!",
    ["对咯！后来这就开了家饺子馆，这饺子馆啊，"] = "ƫƽảƾǦđƚ!ǦƮƶǊǦǃƐǓǦǃƼườƾǦǉƶǦǂởǦǂộǉǦǆǊƑǃǦǈủƾǦƸảǄǦởǦđƁǓ,ǦƸƑƾǦǆǊƑǃǦǃƐǓǦấǓǦƐ,",
    ["一开，转眼也是百年了....."] = "ƨởǦǂộǉǦǂạƸƽǦǉƽấǂǦǉƽǄƑǉǦƸũǃƼǦđƃǦǉǇăǂǦǃăǂǦǇồƾ.....",
    ["你还没吃过他家饺子吧？快，去找张全下一碗！"] = "ƩƼươƾǦƸƽưƶǦăǃǦǈủƾǦƸảǄǦǃƽƐǦǃƐǓǦƷƶǄǦƼƾờǦǅƽảƾǦǀƽƇǃƼ?ǦƨƶǊ,ǦđƾǦǉƔǂǦǥǇươǃƼǦǥǄƐǃǦǁƐǂǦǂộǉǦƷƑǉ!",
    ["说不定啊，百年以后，你今儿吃的饺子，也成传说了！"] = "ƝƾếǉǦđƁǊǦđấǓ,ǦǉǇăǂǦǃăǂǦǈƶǊ,ǦƷƑǉǦǈủƾǦƸảǄǦǃƼươƾǦăǃǦƽƇǂǦǃƶǓǦƸũǃƼǦǉǇởǦǉƽƐǃƽǦǉǇǊǓềǃǦǉƽǊǓếǉǦǇồƾ!",
    ["一二三四五，人齐了。我再说一次，今晚的攀登，"] = "ƨộǉǦƽƶƾǦƷƶǦƷốǃǦǃăǂ,ǦđủǦǃƼườƾǦǇồƾ.ǦǥƶǦǃƚƾǦǁạƾǦǁầǃǦǃữƶ,ǦƸƽǊǓếǃǦǁƺǄǦǃƕƾǦǉốƾǦǃƶǓ,",
    ["还是要注意安全，都跟紧了，别掉队啊。"] = "ƱẫǃǦǅƽảƾǦƸƽƕǦƈǦƶǃǦǉǄƐǃ,ǦđềǊǦđƾǦǈƑǉǦǋƐǄǦǃƽƶǊ,ǦđừǃƼǦđểǦǁạƸǦđǄƐǃ.",
    ["是的，大家都听梅成的，他有经验。"] = "ĐƕǃƼǦǋậǓ,ǦǂọƾǦǃƼườƾǦƸứǦǃƼƽƺǦǉƽƺǄǦƨƶƾǦǥƽƐǃƽ,ǦƽǊǓǃƽǦấǓǦƸƚǦǀƾǃƽǦǃƼƽƾệǂ.",
    ["你们也准备登山？"] = "ƞƑƸǦǃƼươƾǦƸũǃƼǦƸƽǊẩǃǦƷịǦǁƺǄǦǃƕƾǦǈƶǄ?",
    ["是呀，我们约好了在这集中呢。你也是来登峰的？"] = "ƫƽảƾǦđƚ,ǦƸƽƕǃƼǦǉƶǦƽẹǃǦǃƽƶǊǦǉậǅǦǉǇǊǃƼǦởǦđƁǓ.ǦƣǊǓǃƽǦđƐƾǦƸũǃƼǦǉớƾǦǁƺǄǦđỉǃƽǦƐ?",
    ["看你有点面生啊。要是第一次登山可要注意些，夜里还是有点危险的。"] = "ǥǇƇǃƼǦƽǊǓǃƽǦƽơƾǦǁạǦǂặǉ.ǦƩếǊǦǁƐǦǁầǃǦđầǊǦǁƺǄǦǃƕƾǦǉƽƔǦǅƽảƾǦƸƽƕǦƈǦƸƽƕǉ,ǦƷƶǃǦđƙǂǦƸƚǦƽơƾǦǃƼǊǓǦƽƾểǂǦđấǓ.",
    ["对咯，一帆也是第一次登峰吧？你也注意点脚下，跟紧我们啊！"] = "ĐƕǃƼǦǇồƾ,ǦƩƽấǉǦƫƽƐǂǦƸũǃƼǦǁƐǦǁầǃǦđầǊǦǁƺǄǦđỉǃƽǦǅƽảƾǦǀƽƇǃƼ?ǦĐệǦƸũǃƼǦƸƽƕǦƈǦǤướƾǦƸƽƁǃ,ǦǉƽƺǄǦǈƑǉǦƷọǃǦǉƶǦǃƽƗ!",
    ["对，万一真有什么突发情况，掉队了，"] = "ĐƕǃƼ,ǦǋạǃǦǃƽấǉǦƸƚǦǉƔǃƽǦƽǊốǃƼǦƷấǉǦǃƼờǦƼƔǦǂƐǦǁạƸǦđǄƐǃ,",
    ["记得大喊张叔，说不定有人能救你一命！"] = "ƩƽớǦƽƗǉǦǉƽậǉǦǉǄǦƼọƾǦǉƽƕƸǦǥǇươǃƼ,ǦƷƾếǉǦđƁǊǦǁạƾǦƸƚǦǃƼườƾǦƸứǊǦđượƸǦǂộǉǦǂạǃƼ!",
    ["对对对，张叔张叔，张叔在....."] = "ƫƽảƾǦǅƽảƾǦǅƽảƾ,ǦǉƽƕƸǦǥǇươǃƼǦǉƽƕƸǦǥǇươǃƼ,ǦǉƽƕƸǦǥǇươǃƼǦở.....",
    ["是的。"] = "ĐƕǃƼǦǋậǓ.",
    ["你说就差我了？这也没人啊……"] = "ƩƼươƾǦǃƚƾǦƸƽỉǦǉƽƾếǊǦǂỗƾǦǉƶ?ǦỞǦđƁǓǦƸƚǦƶƾǦđƁǊǦǃƐǄ……",
    ["你人先来，俺才能挑啊。"] = "ƩƼươƾǦǅƽảƾǦǉớƾǦǉǇướƸ,ǦǁƃǄǦǂớƾǦƼƑǃƽǦđượƸǦƸƽứ.",
    ["挑什么？"] = "ƢƑǃƽǦƸƑƾǦƼƔ?",
    ["挑山上去啊，你只管来，俺只管挑，飞一下不？"] = "ƢƑǃƽǦǁƙǃǦǃƕƾǦƸƽứǦƼƔ,ǦǃƼươƾǦƸứǦǋƾệƸǦđếǃ,ǦǁƃǄǦƸứǦǋƾệƸǦƼƑǃƽ,ǦƷƶǓǦǂộǉǦƸƽǊǓếǃǦǀƽƇǃƼ?",
    ["游侠留步……游侠——"] = "ǝǊǦƽƾệǅǦǤừǃƼǦƷướƸ……ǦǝǊǦƽƾệǅǦ——",
    ["游侠……请留步啊游侠……"] = "ǝǊǦƽƾệǅ……ǦƳƾǃǦǤừǃƼǦƷướƸ,ǦǤǊǦƽƾệǅǦơƾ……",
    ["还爬吗......"] = "ƞƛǃǦǁƺǄǦǃữƶǦǀƽƇǃƼ......",
    ["还有半程，客官要不要上轿？"] = "ƞƛǃǦǃửƶǦƸƽặǃƼǦǃữƶ,ǦǀƽƑƸƽǦǆǊƶǃǦƸƚǦǂǊốǃǦǁƙǃǦǀƾệǊǦǀƽƇǃƼ?",
    ["多少钱？"] = "ƝƶǄǦǃƽƾƙǊǦǉƾềǃ?",
    ["到南天门，二两银子。"] = "ĐếǃǦƩƶǂǦǥƽƾƙǃǦƨƇǃ,ǦƽƶƾǦǁạǃƼǦƷạƸ.",
    ["二两？！我自己走！"] = "ƣƶƾǦǁạǃƼ?!ǦǥƶǦǉựǦđƾ!",
    ["又一个这么说的，待会儿还得回来找我们。"] = "ƧạƾǦǂộǉǦǃƼườƾǦǃƚƾǦǉƽế,ǦǁƑǉǦǃữƶǦǉƽếǦǃƐǄǦƸũǃƼǦǆǊƶǓǦǁạƾǦǉƔǂǦǉụƾǦǃƐǓǦǉƽƇƾ.",
    ["灯笼灯笼——山道黑，提一盏照路嘞！"] = "ƧồǃƼǦđƘǃǦđƁǓǦǁồǃƼǦđƘǃǦđƁǓǦ——ǦđườǃƼǦǃƕƾǦǉốƾǦǉăǂ,ǦǍƑƸƽǦǂộǉǦƸƽƾếƸǦǈǄƾǦđườǃƼǦđƾ!",
    ["给我来一盏。"] = "ƞƽǄǦǉƶǦǂộǉǦƸƽƾếƸ.",
    ["你不有火折子吗？"] = "ƞƽẳǃƼǦǅƽảƾǦǃƼươƾǦƸƚǦƽỏƶǦƸƽƾếǉǦǉửǦ(ốǃƼǦǆǊẹǉ)ǦǈƶǄ?",
    ["火折子哪有灯笼好看。你看这上头画的，是泰山奶奶吧？"] = "ƣỏƶǦƸƽƾếǉǦǉửǦǈƶǄǦđẹǅǦƷằǃƼǦǁồǃƼǦđƘǃǦđượƸ.ǦƩƼươƾǦǍƺǂǦƽƔǃƽǦǋẽǦǉǇƙǃǦǃƐǓ,ǦǁƐǦǥƽƑƾǦƮơǃǦǃƃƾǦǃƃƾǦǅƽảƾǦǀƽƇǃƼ?",
    ["客官好眼力！碧霞元君保佑，一路平安，心想事成！"] = "ƦƽƑƸƽǦǆǊƶǃǦǉƾǃƽǦǂắǉǦǉƽậǉ!ǦƝƓƸƽǦƣƐǦƩƼǊǓƙǃǦƬǊƁǃǦǅƽƖǦƽộ,ǦǉƽượǃƼǦǁộǦƷƔǃƽǦƶǃ,ǦǋạǃǦǈựǦǃƽưǦƈ!",
    ["阿团兄，走了，山顶有好吃的。"] = "ƜǦĐǄƐǃǦƽǊǓǃƽ,ǦđƾǦǉƽƇƾ,ǦǉǇƙǃǦđỉǃƽǦǃƕƾǦƸƚǦđồǦǃƼǄǃǦǁắǂ.",
    ["再不走，日出就看不到了……要不我背你？"] = "ƦƽƇǃƼǦđƾǦǃữƶǦǁƐǦǀƽƇǃƼǦǃƼắǂǦđượƸǦƷƔǃƽǦǂƾǃƽǦđƁǊ……ǦƣƶǓǦǁƐǦđệǦƸƅǃƼǦƽǊǓǃƽǦǃƽƗ?",
    ["热乎的茶汤、糖糕、炸果子——歇歇脚再走啊客官！"] = "ƩướƸǦǉǇƐǦǃƚǃƼǦƽổƾ,ǦƷƑǃƽǦđườǃƼ,ǦǆǊảǦƸƽƾƙǃǦđƁǓǦ——ǦǃƼƽỉǦƸƽƁǃǦƸƽƕǉǦǇồƾǦđƾǦǀƽƑƸƽǦǆǊƶǃǦơƾ!",
    ["累啦？"] = "ƨệǉǦǇồƾǦƐ?",
    ["这前不着村后不着店的……要不找挑山工先把你扛上去？"] = "ƞƽỗǦǃƐǓǦǉǇướƸǦǀƽƇǃƼǦǉƽƇǃǦǈƶǊǦǀƽƇǃƼǦǆǊƑǃ……ǦƣƶǓǦǁƐǦǉƔǂǦǅƽǊǦƼƑǃƽǦǃƕƾǦǀƽƙǃƽǦƽǊǓǃƽǦǁƙǃǦǉǇướƸǦǃƽƗ?",
    ["还是寻个轿夫连我一起抬？"] = "ƣƶǓǦǁƐǦǉƔǂǦǅƽǊǦǀƾệǊǦǀƽƙǃƽǦǁǊƇǃǦƸảǦđệǦđƾǦƸƖǃƼ?",
    ["罢了，你倒是会享受……"] = "ǥƽƇƾǦđƾ,ǦƽǊǓǃƽǦđƕǃƼǦǁƐǦƷƾếǉǦƽưởǃƼǦǉƽụ……",
    ["这位兄台，它怎么了？"] = "ƱịǦƽǊǓǃƽǦđƐƾǦǃƐǓ,ǦǃƚǦƷịǦǁƐǂǦǈƶǄǦǋậǓ?",
    ["累了呗，死活不肯往上爬。"] = "ƨệǉǦƸƽứǦǈƶǄ,ǦǈốǃƼǦƸƽếǉǦƸũǃƼǦǀƽƇǃƼǦƸƽịǊǦǁƺǄǦǁƙǃǦǃữƶ.",
    ["唉，原想带它来见见世面，谁知这位爷走到这儿就不肯挪步了。"] = "ƣƶƾǏ,ǦǋốǃǦđịǃƽǦǤắǉǦǃƚǦđƾǦǂởǦǂƶǃƼǦǉầǂǦǂắǉ,ǦƶƾǦǃƼờǦǋịǦđạƾǦƼƾƶǦǃƐǓǦđƾǦǉớƾǦđƁǓǦǁƐǦǀƽƇǃƼǦǉƽƘǂǦǃƽƓƸƽǦƷướƸǦǃƐǄǦǃữƶ.",
    ["我正琢磨着要不要请挑山工老兄帮一把呢。"] = "ǥƶǦđƶǃƼǦƸƁǃǦǃƽắƸǦǍƺǂǦƸƚǦǃƙǃǦǃƽờǦƽǊǓǃƽǦđƐƾǦǅƽǊǦƼƑǃƽǦǃƕƾǦƼƾƕǅǦǂộǉǦǉƶǓǦǀƽƇǃƼǦđƁǓ.",
    ["不行了不行了，让我缓口气。"] = "ƦƽƇǃƼǦǍǄǃƼǦǇồƾǦǀƽƇǃƼǦǍǄǃƼǦǇồƾ,ǦƸƽǄǦǉƶǦǉƽởǦǤốƸǦǂộǉǦƸƑƾ.",
    ["刚才谁说“夜爬泰山不过如此”来着？"] = "ƱừƶǦǃƃǓǦđứƶǦǃƐǄǦƷảǄǦ\"ƧƺǄǦǥƽƑƾǦƮơǃǦđƙǂǦƸũǃƼǦǉƽườǃƼǦǉƽƇƾ\"ǦấǓǦǃƽỉ?",
    ["吃你的糖糕吧！"] = "ƧǄǦǂƐǦăǃǦƷƑǃƽǦđườǃƼǦƸủƶǦǃƼươƾǦđƾ!",
    ["绿豆汤、红豆汤——客官来一碗？"] = "ƞƶǃƽǦđậǊǦǍƶǃƽ,ǦƸƶǃƽǦđậǊǦđỏǦ——ǦǀƽƑƸƽǦǆǊƶǃǦǁƐǂǦǂộǉǦƷƑǉǦǀƽƇǃƼ?",
    ["来一碗！多少钱？"] = "ƞƽǄǦǂộǉǦƷƑǉ!ǦƝƶǄǦǃƽƾƙǊǦǉƾềǃ?",
    ["三文钱，包您喝了腿脚有劲，一口气上南天门！"] = "ƝƶǦǋăǃǦǉƾềǃ,ǦđảǂǦƷảǄǦǃƼƐƾǦǊốǃƼǦǍǄǃƼǦƸƽƁǃǦǉƶǓǦǀƽỏƺǦǀƽǄắǃ,ǦǁƺǄǦǂộǉǦǂạƸƽǦǁƙǃǦƩƶǂǦǥƽƾƙǃǦƨƇǃ!",
    ["痛快！再来一碗！"] = "ƮảǃƼǦǀƽǄƑƾ!ǦƞƽǄǦǉƽƙǂǦƷƑǉǦǃữƶ!",
    ["小老师，且停步！"] = "ǥƾểǊǦǁƃǄǦǈư,ǦǍƾǃǦǤừǃƼǦƷướƸ!",
    ["这泰山上不得啊上不得！"] = "ǥƽƑƾǦƮơǃǦǃƐǓǦǀƽƇǃƼǦǁƙǃǦđượƸ,ǦǀƽƇǃƼǦǁƙǃǦđượƸǦđƁǊ!",
    ["上了泰山，命格不对，十死无生啊……"] = "ƧƙǃǦǥƽƑƾǦƮơǃ,ǦǂệǃƽǦƸƑƸƽǦǀƽƇǃƼǦƽợǅ,ǦǁƐǦǉƽậǅǦǉửǦǋƇǦǈƾǃƽǦđƚ……",
    ["要不比试一场？"] = "ƣƶǓǦǁƐǦǉỷǦǉƽƓǦǂộǉǦǉǇậǃ?",
    ["比试什么，登山？看谁最早爬上去？"] = "ǥỷǦǉƽƓǦƸƑƾǦƼƔ,ǦǁƺǄǦǃƕƾǦƐ?ǦƳƺǂǦƶƾǦǁƙǃǦǉớƾǦđỉǃƽǦǈớǂǦǃƽấǉ?",
    ["我觉得不错，要不比比？"] = "ǥƶǦǉƽấǓǦđượƸǦđƚ,ǦƽƶǓǦǁƐǦǈǄǦǉƽử?",
    ["行啊，输了的等会下山请吃饺子！"] = "ĐượƸǦǉƽƇƾ,ǦǀẻǦǃƐǄǦǉƽǊƶǦǁƑǉǦǃữƶǦǍǊốǃƼǦǃƕƾǦǂờƾǦăǃǦǈủƾǦƸảǄ!",
    ["有意思，这回肯定我第一！"] = "ǥƽƕǦǋịǦđấǓ,ǦǁầǃǦǃƐǓǦƸƽắƸǦƸƽắǃǦǉƶǦƽạǃƼǦǃƽấǉ!",
    ["话别说太早，咱这有高手！"] = "ĐừǃƼǦǃƚƾǦǈớǂǦǆǊƑ,ǦƸƽỗǦǉƶǦƸƚǦƸƶǄǦǉƽủǦđấǓ!",
    ["来来来，我倒要看看！"] = "ǥớƾǦǁǊƇǃǦđƾ,ǦǉƶǦƸũǃƼǦǂǊốǃǦǂởǦǉầǂǦǂắǉ!",
    ["观小老师面相，可是丙午年生人？"] = "ƳƺǂǦǤƾệǃǦǂạǄǦǉƾểǊǦǁƃǄǦǈư,ǦƸƚǦǅƽảƾǦǁƐǦǃƼườƾǦǈƾǃƽǦǃăǂǦƝƓǃƽǦƩƼọ?",
    ["丙午为天河水命，火马之身。我算到小老师"] = "ƝƓǃƽǦƩƼọǦǁƐǦǂệǃƽǦǥƽƾƙǃǦƣƐǦǥƽủǓ,ǦǉƽƁǃǦƣỏƶǦƨƃ.ǦƧƃǄǦǅƽǊǦƷấǂǦǆǊẻǦǉƽấǓǦǉƾểǊǦǁƃǄǦǈư",
    ["十六岁那年遇过一场火劫，正是应了此番命格。"] = "ƩăǂǦǂườƾǦǈƑǊǦǉǊổƾǦǉừǃƼǦƼặǅǦǂộǉǦǉǇậǃǦƽỏƶǦǀƾếǅ,ǦƸƽƓǃƽǦǁƐǦứǃƼǦǋớƾǦǂệǃƽǦƸƑƸƽǦǃƐǓ.",
    ["火马遇火劫而能全身，此乃童子命是也。"] = "ƣỏƶǦƨƃǦƼặǅǦƽỏƶǦǀƾếǅǦǂƐǦƸƚǦǉƽểǦǉǄƐǃǦǉƽƁǃǦǃƽƾǦǉƽốƾ,ǦđƁǓǦƸƽƓǃƽǦǁƐǦǂạǃƼǦĐồǃƼǦǥửǦǋậǓ.",
    ["童子命亦是仙童命，乃侍奉神仙的小童因种种缘由，转世下凡。"] = "ƨạǃƼǦĐồǃƼǦǥửǦƸũǃƼǦǁƐǦǂạǃƼǦǥƾƙǃǦĐồǃƼ,ǦǋốǃǦǁƐǦǉƾểǊǦđồǃƼǦƽầǊǦƽạǦǉƽầǃǦǉƾƙǃǦǋƔǦǃƽƾềǊǦƸăǃǦǃƼǊǓƙǃǦǂƐǦƸƽǊǓểǃǦǉƽếǦǍǊốǃƼǦǉǇầǃ.",
    ["你八字带火煞，年少必历劫。这本是上天在收你回去，"] = "ƝƑǉǦǉựǦƸủƶǦǃƼươƾǦǂƶǃƼǦƣỏƶǦƮƑǉ,ǦǁƕƸǦǉǇẻǦắǉǦǅƽảƾǦǉǇảƾǦǆǊƶǦđạƾǦǀƾếǅ.ǦĐƁǓǦǋốǃǦǁƐǦƈǦǉǇờƾǦǂǊốǃǦǉƽǊǦǃƼươƾǦǋề,",
    ["你命里有仙根，方才抗住，如今又遇泰山，怕是又有一劫。"] = "ƨệǃƽǦƸủƶǦǃƼươƾǦƸƚǦǉƾƙǃǦƸăǃǦǃƙǃǦǂớƾǦǉǇụǦǋữǃƼǦđượƸǦđếǃǦƼƾờ,ǦǃƶǓǦǁạƾǦƼặǅǦǥƽƑƾǦƮơǃ,ǦǈợǦǇằǃƼǦǁạƾǦƸƚǦǂộǉǦǀƾếǅǦǃữƶ.",
    ["小老师有所不知，东岳乃天帝驻地，童子入岳，"] = "ǥƾểǊǦǁƃǄǦǈưǦƸƚǦđƾềǊǦǀƽƇǃƼǦƷƾếǉ,ǦĐƇǃƼǦƩƽạƸǦǁƐǦǃơƾǦǥƽƾƙǃǦĐếǦǃƼựǦǉǇị,ǦǉƽƁǃǦĐồǃƼǦǥửǦǋƐǄǦǃƕƾ,",
    ["如孤羊入虎口，一旦被值日功曹察觉，必被引回天庭。"] = "ƞƽẳǃƼǦǀƽƑƸǦǃƐǄǦƸừǊǦǃǄǃǦǁọǉǦǂƾệǃƼǦƽổ,ǦǂộǉǦǀƽƾǦƷịǦǥǇịǦƩƽậǉǦƞƇǃƼǦǥƐǄǦǅƽƑǉǦƼƾƑƸ,ǦắǉǦǈẽǦƷịǦǤẫǃǦƼƾảƾǦǋềǦǥƽƾƙǃǦĐƔǃƽ.",
    ["待到那时，你便魂魄离体，一命呜呼！"] = "ĐếǃǦǁƕƸǦđƚ,ǦǃƼươƾǦǈẽǦƽồǃǦǁƔƶǦǀƽỏƾǦǍƑƸ,ǦǂấǉǦǂạǃƼǦǃƽưǦƸƽơƾ!",
    ["也罢，贫道不远处那位山天兄弟八字甲子、丁卯、乙亥、己卯，"] = "ǥƽƇƾǦđượƸǦǇồƾ,ǦǋịǦƽǊǓǃƽǦđệǦƮơǃǦǥƽƾƙǃǦởǦƸƑƸƽǦƷầǃǦđạǄǦǀƽƇǃƼǦǍƶǦǀƾƶǦƸƚǦƷƑǉǦǉựǦƢƾƑǅǦǥƈ,ǦĐƾǃƽǦƨƃǄ,ǦẤǉǦƣợƾ,ǦƦỷǦƨƃǄ,",
    ["乃是乙木生于卯月，地支亥卯半合木局，天干甲丁相生。"] = "ƞƽƓǃƽǦǁƐǦẤǉǦƨộƸǦǈƾǃƽǦǋƐǄǦǉƽƑǃƼǦƨƃǄ,ǦđịƶǦƸƽƾǦƣợƾǦƨƃǄǦƷƑǃǦƽợǅǦƨộƸǦƸụƸ,ǦǉƽƾƙǃǦƸƶǃǦƢƾƑǅǦĐƾǃƽǦǉươǃƼǦǈƾǃƽ.",
    ["木旺之命，木生火旺，可以火乱火。让他送你一程，或可避祸。"] = "ƨệǃƽǦƨộƸǦǋượǃƼ,ǦƨộƸǦǈƾǃƽǦƣỏƶǦǋượǃƼ,ǦƸƚǦǉƽểǦǤƖǃƼǦƣỏƶǦǁǄạǃǦƣỏƶ.ǦĐểǦƽắǃǦǉƾễǃǦǃƼươƾǦǂộǉǦđǄạǃ,ǦƽọƶǦǂƶǓǦǉǇƑǃƽǦđượƸǦǉƶƾǦươǃƼ.",
    ["唉，言尽于此。小老师若不信命理之说，贫道也不强求。"] = "ƣƶƾǏ,ǦǁờƾǦđƃǦǃƚƾǦƽếǉǦǇồƾ.ǦƩếǊǦǉƾểǊǦǁƃǄǦǈưǦǀƽƇǃƼǦǉƾǃǦƸƽǊǓệǃǦǂệǃƽǦǁƈ,ǦƷầǃǦđạǄǦƸũǃƼǦǀƽƇǃƼǦƗǅ.",
    ["只有最后一言，若上山时觉得头晕目眩，切莫回头。"] = "ƞƽỉǦƸƛǃǦǂộǉǦǁờƾǦƸǊốƾ,ǦǃếǊǦǁƕƸǦǁƙǃǦǃƕƾǦǉƽấǓǦđầǊǦǋƑǃƼǦǂắǉǦƽǄƶ,ǦǉǊǓệǉǦđốƾǦđừǃƼǦǆǊƶǓǦđầǊǦǁạƾ.",
    ["小老师，挑一下不？"] = "ǥƾểǊǦǁƃǄǦǈư,ǦƸƚǦƼƑǃƽǦǂộǉǦƸƽǊǓếǃǦǀƽƇǃƼ?",
    ["俺这挑山的本事不孬吧？稳当！安全！跟坐轿似的！"] = "ƝảǃǦǁĩǃƽǦƼƑǃƽǦǃƕƾǦƸủƶǦǁƃǄǦǀƽƇǃƼǦǉồƾǦƸƽứ?ǦƱữǃƼǦƸƽƃƾ!ǦƜǃǦǉǄƐǃ!ǦƞứǦǃƽưǦǃƼồƾǦǀƾệǊǦǋậǓ!",
    ["真安全？"] = "ƜǃǦǉǄƐǃǦǉƽậǉǦǀƽƇǃƼ?",
    ["人家爬泰山，怕风怕雨怕大虫。让俺来挑，眼一闭，再一睁——到顶了！"] = "ƩƼườƾǦǉƶǦǁƺǄǦǥƽƑƾǦƮơǃ,ǦǈợǦƼƾƚǦǈợǦǂưƶǦǈợǦƽổǦǤữ.ǦƞứǦđểǦǁƃǄǦƼƑǃƽǦƸƽǄ,ǦǃƽắǂǦǂắǉǦǁạƾ,ǦǇồƾǦǂởǦǂắǉǦǇƶǦ——ǦǉớƾǦđỉǃƽǦǇồƾ!",
    ["小老师，飞一下不？"] = "ǥƾểǊǦǁƃǄǦǈư,ǦƷƶǓǦǂộǉǦƸƽǊǓếǃǦǀƽƇǃƼ?",
    ["我从岭南来，只道登过丹霞山便天下无敌了，谁想这泰山这么要命……"] = "ǥƶǦǉừǦƧĩǃƽǦƩƶǂǦǉớƾ,ǦƸứǦǃƼỡǦǁƺǄǦđượƸǦĐƶǃǦƣƐǦƮơǃǦǁƐǦǉƽƾƙǃǦƽạǦǋƇǦđịƸƽǦǇồƾ,ǦƶƾǦǤƘǦƸƑƾǦǥƽƑƾǦƮơǃǦǃƐǓǦǁạƾǦǁấǓǦǂạǃƼǦǃƼườƾǦǉƶǦǉƽếǦǃƐǓ……",
    ["岭南来的？我蜀中的，翻过剑门关都没觉着这般费劲。"] = "ǥừǦƧĩǃƽǦƩƶǂǦǉớƾǦǈƶǄ?ǦǥƶǦǉừǦǥƽụƸǦǥǇǊǃƼǦđƁǓ,ǦƸƚǦǋượǉǦǆǊƶǦƦƾếǂǦƨƇǃǦƬǊƶǃǦƸũǃƼǦƸƽưƶǦǉƽấǓǦǉốǃǦǈứƸǦđếǃǦǂứƸǦǃƐǓ.",
    ["这泰山啊，它不是险，它是绵！"] = "ƞƑƾǦǃƕƾǦǥƽƑƾǦƮơǃǦǃƐǓǦấǓǦƐ,ǦǃƚǦǀƽƇǃƼǦƽƾểǂ,ǦǂƐǦǃƚǦǤƶƾ!",
    ["歇会儿......"] = "ƩƼƽỉǦǉƓǦđƃ......",
    ["我不行了......现在下山，还来得及吗......"] = "ǥƶǦƽếǉǦƽơƾǦǇồƾ......ǦƝƁǓǦƼƾờǦǍǊốǃƼǦǃƕƾ,ǦƸƛǃǦǀịǅǦǀƽƇǃƼǦǃƽỉ......",
    ["来都来了，要不......"] = "ĐƃǦǉớƾǦǉậǃǦđƁǓǦǇồƾ,ǦƽƶǓǦǁƐ......",
    ["现在下山也得好一会......我都行......你爬我就爬！"] = "ƝƁǓǦƼƾờǦǍǊốǃƼǦǃƕƾǦƸũǃƼǦǂấǉǦǂộǉǦǁƕƸǦđấǓ......ǦǥƶǦǉƽếǦǃƐǄǦƸũǃƼǦđượƸ......ǦƩƼươƾǦǁƺǄǦǉƽƔǦǉƶǦǁƺǄ!",
    ["你爬我也爬！"] = "ƩƼươƾǦǁƺǄǦǉƶǦƸũǃƼǦǁƺǄ!",
    ["那接着爬？"] = "ǥƽếǦǁƺǄǦǉƾếǅǦǃƽƗ?",
    ["可是离登顶还有一大段路......"] = "ƩƽưǃƼǦǂƐǦǉừǦđƁǓǦǁƙǃǦǉớƾǦđỉǃƽǦƸƛǃǦǍƶǦǁắǂ......",
    ["那我们下山......？"] = "ƣƶǓǦǁƐǦǂƔǃƽǦǍǊốǃƼǦǃƕƾ......?",
    ["可是来都来了......"] = "ƩƽưǃƼǦǂƐǦđƃǦǉớƾǦǉậǃǦđƁǓǦǇồƾ......",
    ["文津馆老人"] = "ƧƃǄǦǃƽƁǃǦƱăǃǦǥƁǃǦƬǊƑǃ",
    ["一棵树也能封官？"] = "ƨộǉǦƸƑƾǦƸƁǓǦǂƐǦƸũǃƼǦđượƸǦǅƽǄǃƼǦǆǊƶǃǦǈƶǄ?",
    ["俺也歇歇脚，蹭蹭贵气，保不齐回去生意兴隆哩！"] = "ƧƃǄǦƸũǃƼǦǃƼƽỉǦƸƽƁǃǦƸƽƕǉ,ǦƽưởǃƼǦƓǉǦǆǊƈǦǀƽƓ,ǦƷƾếǉǦđƁǊǦǋềǦǃƽƐǦǁƐǂǦăǃǦǁạƾǦǅƽƑǉǦǉƐƾ!",
    ["今日便由松大夫作我座中主考，听我论辩！咳咳——！"] = "ƣƇǂǦǃƶǓǦǍƾǃǦǂờƾǦǥƖǃƼǦđạƾǦǅƽǊǦǁƐǂǦƸƽủǦǀƽảǄ,ǦǃƼƽƺǦǉƶǦǁǊậǃǦƷƾệǃ!ǦƦƽụǦǀƽụǦ——!",
    ["唉，明日赴考，若主考官也是棵松树，那便好办了……"] = "ƣƶƾǏ,ǦǃƼƐǓǦǂƶƾǦđƾǦǉƽƾ,ǦǃếǊǦƸƽủǦǀƽảǄǦǆǊƶǃǦƸũǃƼǦǁƐǦǂộǉǦƸƑƾǦƸƁǓǦǉƖǃƼǦǉƽƔǦǤễǦƷềǦƽƐǃƽǦǈựǦǇồƾ……",
    ["怎么独自在此对着棵松树耍嘴皮子？"] = "ƮƶǄǦǁạƾǦǂộǉǦǉƽƁǃǦǂộǉǦǂƔǃƽǦđứǃƼǦđƁǓǦǀƽǊƶǦǂƇƾǦǂƕƶǦǂƗǅǦǋớƾǦƸƑƾǦƸƁǓǦǉƖǃƼǦǉƽếǦǃƐǓ?",
    ["基础操作：游侠通过选择流派搭配#Y话术卡、妙语卡、箴言卡#E组建卡组。在对战期间，#Y拖动#E手中卡牌到任意区域可以打出对应的卡牌。\n其中，箴言卡选自论语，每张箴言卡每场对决至多使用1次。\n胜负判定：双方各有#Y三路心防#E，分别为#Y侠胆、文心和洞察#E，将对手#Y任意一路心防#E打至零即可攻击对方神志获得胜利；己方任意一路心防被打至零且神志受到伤害则失败。"] = "ǥƽƶǄǦǉƑƸǦƸơǦƷảǃ:ǦǝǊǦƽƾệǅǦǉƽƇǃƼǦǆǊƶǦƸƽọǃǦǁưǊǦǅƽƑƾǦđểǦǅƽốƾǦƽợǅǦ#YǥƽǄạƾǦǥƽǊậǉǦǥƽẻ,ǦǝƾệǊǦƩƼữǦǥƽẻ,ǦƞƽƁǂǦƩƼƇǃǦǥƽẻ#EǦǍƁǓǦǤựǃƼǦƷộǦǉƽẻ.ǦǥǇǄǃƼǦǁƕƸǦđốƾǦƸƽƾếǃ,Ǧ#YǀƗǄ#EǦǉƽẻǦƷƐƾǦǉǇƙǃǦǉƶǓǦđếǃǦǀƽǊǦǋựƸǦƷấǉǦǀỳǦđểǦđƑǃƽǦǇƶǦǉƽẻǦǉươǃƼǦứǃƼ.\nǥǇǄǃƼǦđƚ,ǦƞƽƁǂǦƩƼƇǃǦǥƽẻǦđượƸǦƸƽọǃǦǉừǦƧǊậǃǦƩƼữ,ǦǂỗƾǦǉấǂǦƞƽƁǂǦƩƼƇǃǦǥƽẻǦǂỗƾǦǋƑǃǦđốƾǦǆǊǓếǉǦƸƽỉǦđượƸǦǤƖǃƼǦǉốƾǦđƶǦ1Ǧǁầǃ.\nƫƽƑǃǦđịǃƽǦǉƽắǃƼǦǉƽǊƶ:ǦƣƶƾǦƷƙǃǦǂỗƾǦƷƙǃǦƸƚǦ#YƷƶǦđườǃƼǦǉƁǂǦǅƽƛǃƼ#E,ǦǁầǃǦǁượǉǦǁƐǦ#YƣƾệǅǦĐảǂ,ǦƱăǃǦǥƁǂǦǋƐǦĐộǃƼǦƮƑǉ#E,ǦđƑǃƽǦ#YƷấǉǦǀỳǦǂộǉǦđườǃƼǦǉƁǂǦǅƽƛǃƼ#EǦǃƐǄǦƸủƶǦđốƾǦǉƽủǦǋềǦǀƽƇǃƼǦǁƐǦƸƚǦǉƽểǦǉấǃǦƸƇǃƼǦǉƽầǃǦƸƽƓǦđốƾǦǅƽươǃƼǦđểǦƼƾƐǃƽǦƸƽƾếǃǦǉƽắǃƼ;ǦǃếǊǦƷấǉǦǀỳǦđườǃƼǦǉƁǂǦǅƽƛǃƼǦǃƐǄǦƸủƶǦƷảǃǦǉƽƁǃǦƷịǦđƑǃƽǦǋềǦǀƽƇǃƼǦǋƐǦǉƽầǃǦƸƽƓǦƸƽịǊǦǈƑǉǦǉƽươǃƼǦǉƽƔǦǉƽấǉǦƷạƾ.",
    ["#Y口出狂言#E：#Y快攻流#E，命中心防可叠鼓舞层，每层增加总攻；三路满层后定期免费出牌。\n#Y大力扎心#E：#Y绕路流#E，话术卡每次通过暗度陈仓绕路成功将降低对方存在感，触发3次将#Y秒杀#E对方卡牌。\n#Y气人杠精#E：#Y成长流#E，击败敌方话术卡可提升思路点回复速度及上限，积累优势后一击制胜。\n#Y废话连篇#E：#Y防守流#E，话术卡对撞后产生废话卡堆在心防前；积累到位后利用箴言卡一次性爆发清场。"] = "#YƦƽẩǊǦƳǊấǉǦƞǊồǃƼǦƩƼƇǃ#E:Ǧ#YƦƽǄƑƾǦƞƇǃƼǦƧưǊ#E,ǦđƑǃƽǦǉǇƕǃƼǦǥƁǂǦƫƽƛǃƼǦƸƚǦǉƽểǦǉƓƸƽǦǉầǃƼǦƞổǦƱũ,ǦǂỗƾǦǉầǃƼǦǉăǃƼǦǥổǃƼǦƞƇǃƼ;ǦǈƶǊǦǀƽƾǦƷƶǦđườǃƼǦđầǓǦǉầǃƼǦǈẽǦđịǃƽǦǀỳǦǇƶǦƷƐƾǦǂƾễǃǦǅƽƓ.\n#YĐạƾǦƧựƸǦǥǇƑǉǦǥƁǂ#E:Ǧ#YƩƽƾễǊǦƧộǦƧưǊ#E,ǦǉƽẻǦǥƽǄạƾǦǥƽǊậǉǦǂỗƾǦǀƽƾǦǉƽƇǃƼǦǆǊƶǦÁǂǦĐộǦǥǇầǃǦǥƽươǃƼǦǃƽƾễǊǦǁộǦǉƽƐǃƽǦƸƇǃƼǦǈẽǦƼƾảǂǦƷớǉǦǈựǦǉồǃǦǉạƾǦƸủƶǦđốƾǦǅƽươǃƼ,ǦǀƓƸƽǦƽǄạǉǦ3ǦǁầǃǦǈẽǦ#YƮƑǉǦǥƽủ#EǦǉƽẻǦƷƐƾǦđốƾǦǅƽươǃƼ.\n#YƦƽƓǦƩƽƁǃǦƞƑǃƼǦǥƾǃƽ#E:Ǧ#YǥƽƐǃƽǦǥǇưởǃƼǦƧưǊ#E,ǦđƑǃƽǦƷạƾǦǉƽẻǦǥƽǄạƾǦǥƽǊậǉǦǀẻǦđịƸƽǦƸƚǦǉƽểǦǉăǃƼǦǉốƸǦđộǦƽồƾǦǅƽụƸǦǋƐǦƼƾớƾǦƽạǃǦǥưǦƧộǦĐƾểǂ,ǦǉƓƸƽǦǁũǓǦưǊǦǉƽếǦǇồƾǦǂộǉǦđƛǃǦƸƽếǦǉƽắǃƼ.\n#YƫƽếǦǥƽǄạƾǦƧƾƙǃǦǥƽƾƙǃ#E:Ǧ#YƫƽƛǃƼǦǥƽủǦƧưǊ#E,ǦǉƽẻǦǥƽǄạƾǦǥƽǊậǉǦǈƶǊǦǀƽƾǦđốƾǦđầǊǦǈẽǦǉạǄǦǇƶǦƸƽồǃƼǦǉƽẻǦƫƽếǦǥƽǄạƾǦƸƽắǃǦǉǇướƸǦǥƁǂǦƫƽƛǃƼ;ǦǈƶǊǦǀƽƾǦǉƓƸƽǦǁũǓǦđủǦǉƽƔǦǤƖǃƼǦǉƽẻǦƞƽƁǂǦƩƼƇǃǦƷộƸǦǅƽƑǉǦǆǊƗǉǦǈạƸƽǦǉǄƐǃǦǉǇườǃƼǦǂộǉǦǁầǃ.",
    ["话山论见规则"] = "ƬǊǓǦǉắƸǦǥƽǄạƾǦƮơǃǦƧǊậǃǦƦƾếǃ",
    ["游侠见笑，鄙人无稽，一心考入文津馆，正对着此松苦苦练习论辩之才。"] = "ǝǊǦƽƾệǅǦƸƽƙǦƸườƾǦǇồƾ,ǦǉạƾǦƽạǦǁƐǦƱƇǦƦƙ,ǦǂộǉǦǁƛǃƼǦǂǊốǃǦǉƽƾǦǋƐǄǦƱăǃǦǥƁǃǦƬǊƑǃ,ǦđƶǃƼǦđứǃƼǦǉǇướƸǦƸƁǓǦǉƖǃƼǦǃƐǓǦǀƽổǦǁǊǓệǃǦǉƐƾǦǁǊậǃǦƷƾệǃ.",
    ["可惜松无言，人无长进，惭愧，惭愧……"] = "ĐƑǃƼǦǉƾếƸǦǉƖǃƼǦƸƽẳǃƼǦǉƽốǉǦǁờƾ,ǦǃƼườƾǦƸƽẳǃƼǦǉƾếǃǦƷộ,ǦƽổǦǉƽẹǃ,ǦƽổǦǉƽẹǃǦǆǊƑ……",
    ["新四大流派特色"] = "ĐặƸǦǈắƸǦƷốǃǦǁưǊǦǅƽƑƾǦǂớƾ",
    ["话术【松下之辩】"] = "ǥƽǊậǉǦǃƼữǦ[ǥƖǃƼǦƣạǦƞƽƾǦƝƾệǃ]",
    ["尚未完成首次挑战"] = "ƞƽưƶǦƽǄƐǃǦǉƽƐǃƽǦǀƽƾƙǊǦƸƽƾếǃǦǁầǃǦđầǊ",
    ["选择话术难度"] = "ƞƽọǃǦđộǦǀƽƚǦǉƽǊậǉǦǃƼữ",
    ["五大夫者，秦爵第九级，秩比千石，位同大夫之尊也。"] = "ƩƼũǦĐạƾǦƫƽǊǦǁƐǦƸấǅǦǉướƸǦǉƽứǦƸƽƓǃǦǉƽờƾǦǥầǃ,ǦƷổǃƼǦǁộƸǦǃƼƶǃƼǦƽƐǃƼǦǃƼƽƔǃǦǉƽạƸƽ,ǦđịƶǦǋịǦǉƇǃǦǆǊƈǦǃƽưǦƷậƸǦđạƾǦǅƽǊǦǋậǓ.",
    ["听讲"] = "ƩƼƽƺǦƼƾảǃƼ",
    ["冒昧请教夫子，这一介草木，何以成为了“大夫”？"] = "ƨạǄǦǂǊộƾǦǉƽỉǃƽǦƼƾƑǄǦǅƽǊǦǉử,ǦƽạǃƼǦǉƽảǄǦǂộƸǦǃƐǓǦǈƶǄǦǁạƾǦƸƚǦǉƽểǦǉǇởǦǉƽƐǃƽǦ\"đạƾǦǅƽǊ\"?",
    ["昔者始皇东巡，风雨骤至，有赖此松避雨，这才得免狼狈。"] = "ƳưƶǦǀƾƶǦǥƽủǓǦƣǄƐǃƼǦǉǊầǃǦǤǊǦǅƽươǃƼǦĐƇǃƼ,ǦǂưƶǦƼƾƚǦƷấǉǦƸƽợǉǦǀƗǄǦđếǃ,ǦǃƽờǦƸƚǦƸƁǓǦǉƖǃƼǦǃƐǓǦƸƽƺǦƸƽắǃǦǂớƾǦǉǇƑǃƽǦǀƽỏƾǦƸảǃƽǦǉƽảǂǦƽạƾ.",
    ["雨过天晴，始皇大悦，便当场下旨，将此松封为“五大夫”。"] = "ƨưƶǦǉạǃƽǦǉǇờƾǦǆǊƶǃƼ,ǦǥƽủǓǦƣǄƐǃƼǦđạƾǦƽỷ,ǦǁƾềǃǦđươǃƼǦǉǇườǃƼǦƽạǦƸƽỉǦǅƽǄǃƼǦƸƁǓǦǉƖǃƼǦǃƐǓǦǁƐǦ\"ƩƼũǦĐạƾǦƫƽǊ\".",
    ["而今松老干虬，秦已灰飞，独此松与山长存……"] = "ƩƶǓǦǉƖǃƼǦđƃǦƼƾƐǦƸỗƾǦƼầǓǦƼǊộƸ,ǦǃƽƐǦǥầǃǦƸũǃƼǦđƃǦǉƶǃǦǉƽƐǃƽǦǉǇǄǦƷụƾ,ǦƸƽỉǦƸƚǦƸƁǓǦǉƖǃƼǦǃƐǓǦǁƐǦǉǇườǃƼǦǉồǃǦƸƖǃƼǦǃƕƾǦǃǄǃ……",
    ["世易时移，唯有山风不改！"] = "ǥƽếǦđổƾǦǉƽờƾǦǤờƾ,ǦǤǊǓǦƸƽỉǦƸƚǦƼƾƚǦǃƕƾǦǁƐǦǀƽƇǃƼǦđổƾ!",
    ["呵呵，学生所言极是。草木之寿，胜于帝业矣。"] = "ƣƶƽƶ,ǦƽọƸǦǉǇƛǦǃƚƾǦǇấǉǦǅƽảƾ.ǦǥǊổƾǦǉƽọǦƸủƶǦǉƽảǄǦǂộƸǦƸƛǃǦǋữǃƼǦƷềǃǦƽơǃǦƸảǦđếǦǃƼƽƾệǅǦǋậǓ.",
    ["走，咱今晚一定能爬上去！"] = "ĐƾǦǉƽƇƾ,ǦǉốƾǦǃƶǓǦƸƽƕǃƼǦǉƶǦǃƽấǉǦđịǃƽǦǈẽǦǁƺǄǦǁƙǃǦđượƸ!",
    ["区区一座山，拿下！"] = "ƞƽỉǦǁƐǦǂộǉǦǃƼọǃǦǃƕƾ,ǦǍửǦđẹǅ!",
    ["哎哎哎，可不敢这么说！"] = "ƦƔƶǦǀƔƶǦǀƔƶ,ǦǀƽƇǃƼǦđượƸǦǃƚƾǦǉƽếǦđƁǊ!",
    ["走！开爬！"] = "Đƾ!ǦƝắǉǦđầǊǦǁƺǄ!",
    ["喝口水，缓缓。"] = "ǕốǃƼǦǂƾếǃƼǦǃướƸǦđƾ,ǦƸƽǄǦđỡǦǂệǉ.",
    ["多谢……你是第几回爬？"] = "ĐƶǦǉạ……ǦƣǊǓǃƽǦđƐƾǦǁƺǄǦǁầǃǦǉƽứǦǂấǓǦǇồƾ?",
    ["头一回。你呢？"] = "ƧầǃǦđầǊ.ǦƞƛǃǦƽǊǓǃƽ?",
    ["也是头一回。头一回就敢夜爬，咱俩胆子都不小。"] = "ƞũǃƼǦǁƐǦǁầǃǦđầǊ.ǦƧầǃǦđầǊǦǂƐǦđƃǦǤƑǂǦǁƺǄǦđƙǂ,ǦƼƶǃǦƽƶƾǦđứƶǦǂƔǃƽǦƸũǃƼǦǉǄǦǉƽậǉǦđấǓ.",
    ["不是胆子大，是觉得这辈子总得干一件想起来能乐呵的事。"] = "ƦƽƇǃƼǦǅƽảƾǦƼƶǃǦǉǄǦđƁǊ,ǦǂƐǦǁƐǦƸảǂǦǉƽấǓǦđờƾǦǃƐǓǦǃƽấǉǦđịǃƽǦǅƽảƾǦǁƐǂǦǂộǉǦǋƾệƸǦƼƔǦđƚǦđểǦǈƶǊǦǃƐǓǦǃƼƽĩǦǁạƾǦƸƛǃǦǉƽấǓǦǋǊƾǦǋẻ.",
    ["来，尝尝，我们徽州的烧饼，梅干菜肉馅儿的，扛饿。"] = "ƩƐǄ,ǦǃếǂǦǉƽửǦđƾ,ǦƷƑǃƽǦǃướǃƼǦƣǊǓǦƞƽƁǊǦƸủƶǦƸƽƕǃƼǦǉƶ,ǦǃƽƁǃǦǉƽịǉǦǇƶǊǦƸảƾǦǀƽƇ,ǦƸƽắƸǦǤạǦǁắǂ.",
    ["来，尝尝，俺们徽州的烧饼，梅干菜肉馅儿的，扛饿。"] = "ƩƐǄ,ǦǃếǂǦǉƽửǦđƾ,ǦƷƑǃƽǦǃướǃƼǦƣǊǓǦƞƽƁǊǦƸủƶǦǁƃǄ,ǦǃƽƁǃǦǉƽịǉǦǇƶǊǦƸảƾǦǀƽƇ,ǦƸƽắƸǦǤạǦǁắǂ.",
    ["香！回头俺寄些俺们的鲜花饼给你，比这个甜些，又是另一番滋味。"] = "ǥƽơǂǦǉƽậǉ!ǦƮƶǊǦǃƐǓǦǁƃǄǦǈẽǦƼửƾǦƓǉǦƷƑǃƽǦƽǄƶǦǉươƾǦƸủƶǦƸƽỗǦǁƃǄǦƸƽǄǦƽǊǓǃƽ,ǦǃƼọǉǦƽơǃǦƸƑƾǦǃƐǓǦǂộǉǦƸƽƕǉ,ǦǁạƾǦǁƐǦǂộǉǦƽươǃƼǦǋịǦǀƽƑƸǦƽẳǃ.",
    ["那可说定了！俺还没吃过鲜花做的饼呢。"] = "ǥƽếǦǉƽƔǦǆǊǓếǉǦđịǃƽǦǋậǓǦǃƽƗ!ǦƧƃǄǦƸƽưƶǦđượƸǦăǃǦƷƑǃƽǦǁƐǂǦǉừǦƽǄƶǦǉươƾǦƷƶǄǦƼƾờ.",
    ["还有多远啊……"] = "ƞƛǃǦƷƶǄǦǍƶǦǃữƶǦđƁǓ……",
    ["快了快了，过了前面那个弯儿就是。"] = "ƮắǅǦǇồƾǦǈắǅǦǇồƾ,ǦǆǊƶǦƸƑƾǦǀƽƕƸǦǆǊƶǃƽǦǅƽƓƶǦǉǇướƸǦǁƐǦǉớƾ.",
    ["张月，你行的！你指定行！"] = "ǥǇươǃƼǦƩƼǊǓệǉ,ǦǃƼươƾǦǁƐǂǦđượƸ!ǦƞƽắƸǦƸƽắǃǦǃƼươƾǦǁƐǂǦđượƸ!",
    ["最高峰，等着我！"] = "ĐỉǃƽǦƸƶǄǦǃƽấǉ,ǦđợƾǦǉƶǦđấǓ!",
    ["你方才也是这么说的……"] = "ƧƕƸǦǃƃǓǦƽǊǓǃƽǦƸũǃƼǦǃƚƾǦǉƽếǦǂƐ……",
    ["那我换一句，过了这个弯儿的弯儿，准到！"] = "ǥƽếǦǉƽƔǦǉƶǦđổƾǦƸƁǊǦǀƽƑƸ,ǦǆǊƶǦǀƽƕƸǦǆǊƶǃƽǦƸủƶǦƸƑƾǦǀƽƕƸǦǆǊƶǃƽǦǃƐǓ,ǦƸƽắƸǦƸƽắǃǦǉớƾ!",
    ["小老师，又见面了！"] = "ǥƾểǊǦǁƃǄǦǈư,ǦǁạƾǦƼặǅǦǃƽƶǊǦǇồƾ!",
    ["不行了不行了……我就在这儿等着看日出算了……"] = "ƦƽƇǃƼǦǍǄǃƼǦǇồƾǦǀƽƇǃƼǦǍǄǃƼǦǇồƾ……ǦǥƶǦƸứǦởǦđƁǓǦđợƾǦǃƼắǂǦƷƔǃƽǦǂƾǃƽǦǁǊƇǃǦƸƽǄǦǍǄǃƼ……",
    ["别介！都走到这儿了，现在回头多亏啊！"] = "ĐừǃƼǦǂƐ!ǦĐƃǦđƾǦđếǃǦǉậǃǦđƁǓǦǇồƾ,ǦƼƾờǦǆǊƶǓǦǁạƾǦǉƽƔǦǅƽƓǦǁắǂ!",
    ["腿都不是我的了……"] = "ƞƽƁǃǦǀƽƇǃƼǦƸƛǃǦǁƐǦƸủƶǦǉƶǦǃữƶǦǇồƾ……",
    ["我的也不是了！但咱俩的腿加一块儿，总能撑到山顶！"] = "ƞủƶǦđệǦƸũǃƼǦƸƽẳǃƼǦƸƛǃ!ǦƩƽưǃƼǦƸƽƁǃǦƸủƶǦƽƶƾǦǉƶǦƸộǃƼǦǁạƾ,ǦǉƽếǦǃƐǄǦƸũǃƼǦǁếǉǦđượƸǦǁƙǃǦđỉǃƽǦǃƕƾ!",
    ["别叫我小老师，你个骗子——你们是同胞兄弟吧？"] = "ĐừǃƼǦƼọƾǦǉƶǦǁƐǦǉƾểǊǦǁƃǄǦǈư,ǦƸƑƾǦđồǦǁừƶǦđảǄǦ——ǦƸƑƸǦǃƼườƾǦǁƐǦƶǃƽǦƺǂǦƸƖǃƼǦƽǊǓếǉǦǉƽốǃƼǦǅƽảƾǦǀƽƇǃƼ?",
    ["哎，叫恁瞧出来咧——"] = "ƀǓ,ǦƷịǦǃƼƐƾǦǃƽƔǃǦǇƶǦǇồƾǦ——",
    ["小老师，俺们家这挑山的本事怎么样？三百六十行，缺不得咱仨——山行！"] = "ǥƾểǊǦǁƃǄǦǈư,ǦƷảǃǦǁĩǃƽǦƼƑǃƽǦǃƕƾǦǃƽƐǦǁƃǄǦǉƽếǦǃƐǄ?ǦƝƶǦǉǇăǂǦǈƑǊǦǂươƾǦǃƼƽề,ǦǀƽƇǃƼǦǉƽểǦǉƽƾếǊǦƷƶǦđứƶǦǁƃǄǦ——ǦƮơǃǦƣƐǃƽ!",
    ["累了吧？想早到不？想飞不？别管哪个，说“想”就完事了！"] = "ƨệǉǦǇồƾǦǅƽảƾǦǀƽƇǃƼ?ǦƨǊốǃǦđếǃǦǈớǂǦǀƽƇǃƼ?ǦƨǊốǃǦƷƶǓǦǀƽƇǃƼ?ǦƝấǉǦǀểǦƸƑƾǦǃƐǄ,ǦƸứǦǃƚƾǦ\"ǂǊốǃ\"ǦǁƐǦǍǄǃƼǦƸƽǊǓệǃ!",
    ["我刚看见猫了！嗖的一声跑没影了。"] = "ǥƶǦǋừƶǦǉƽấǓǦǂộǉǦƸǄǃǦǂƘǄ!ǦƱụǉǦǂộǉǦƸƑƾǦđƃǦǂấǉǦƽƕǉǦǇồƾ.",
    ["小猫都比我们仨跑得快！"] = "ƨƘǄǦƸǄǃǦƸƛǃǦƸƽạǓǦǃƽƶǃƽǦƽơǃǦƷƶǦđứƶǦǂƔǃƽ!",
    ["我们仨也不差啊，今儿肯定能登上！"] = "ƝƶǦđứƶǦǂƔǃƽǦƸũǃƼǦđƁǊǦƸƚǦǀƗǂ,ǦƽƇǂǦǃƶǓǦǃƽấǉǦđịǃƽǦǁƺǄǦǉớƾǦǃơƾ!",
    ["也是，只要不像上回......."] = "ƞũǃƼǦđƕǃƼ,ǦƸƽỉǦƸầǃǦǀƽƇǃƼǦƼƾốǃƼǦǁầǃǦǉǇướƸ.......",
    ["好了好了不说了，走！"] = "ĐượƸǦǇồƾǦđượƸǦǇồƾǦǀƽƇǃƼǦǃƚƾǦǃữƶ,ǦđƾǦǉƽƇƾ!",
    ["我真的走不动了……"] = "ǥƶǦǉƽựƸǦǈựǦđƾǦǀƽƇǃƼǦǃổƾǦǃữƶǦǇồƾ……",
    ["走得动。你看，前面那个人比你还慢，他不也在走吗？"] = "ĐƾǦđượƸǦǂƐ.ǦƩƼươƾǦǍƺǂ,ǦƸƑƾǦǃƼườƾǦǅƽƓƶǦǉǇướƸǦƸƛǃǦƸƽậǂǦƽơǃǦǃƼươƾ,ǦƸƽẳǃƼǦǅƽảƾǦƽọǦƸũǃƼǦđƶǃƼǦđƾǦđƚǦǈƶǄ?",
    ["那是因为他被人拉着……"] = "ĐƚǦǁƐǦǋƔǦǃƼườƾǦǉƶǦđượƸǦǀƗǄǦđƾ……",
    ["那我也拉着你。咱们一起慢，总比一个人停在那儿强。"] = "ǥƽếǦǉƽƔǦǉƶǦƸũǃƼǦǀƗǄǦǃƼươƾ.ǦƞƽƕǃƼǦǉƶǦƸƖǃƼǦƸƽậǂ,ǦǋẫǃǦǉốǉǦƽơǃǦǁƐǦǂộǉǦǂƔǃƽǦđứǃƼǦǀƽựǃƼǦǁạƾǦđƚ.",
    ["行吧……但你得答应我，到了山顶让我睡一整天。"] = "ĐượƸǦǇồƾ……ǦƩƽưǃƼǦǃƼươƾǦǅƽảƾǦƽứƶǦǋớƾǦǉƶ,ǦǁƙǃǦǉớƾǦđỉǃƽǦǅƽảƾǦđểǦǉƶǦǃƼủǦƸảǦǃƼƐǓǦđấǓ.",
    ["睡两天都行。走！"] = "ƩƼủǦƽƶƾǦǃƼƐǓǦƸũǃƼǦđượƸ.ǦĐƾǦǉƽƇƾ!",
    ["我不行了......"] = "ǥƶǦǀƾệǉǦǈứƸǦǇồƾ......",
    ["我方才问了前面下来的人，说还有三里。"] = "ƧƕƸǦǃƃǓǦđệǦƽỏƾǦǃƼườƾǦǉừǦǉǇƙǃǦđƾǦǍǊốǃƼ,ǦƽọǦƷảǄǦƸƛǃǦƷƶǦǤặǂǦǃữƶ.",
    ["三里？！那不得再爬一个时辰！"] = "ƝƶǦǤặǂ?!ǦǥƽếǦǉƽƔǦƸƽẳǃƼǦǅƽảƾǦǅƽảƾǦǁƺǄǦǉƽƙǂǦǂộǉǦƸƶǃƽǦƼƾờǦǃữƶǦǈƶǄ!",
    ["我又问了一个，说还有两里。"] = "ĐệǦǁạƾǦƽỏƾǦǂộǉǦǃƼườƾǦǀƽƑƸ,ǦƷảǄǦǁƐǦƸƛǃǦƽƶƾǦǤặǂ.",
    ["到底几里？"] = "ƭốǉǦƸǊộƸǦǁƐǦǂấǓǦǤặǂ?",
    ["我又问了一个——"] = "ĐệǦǁạƾǦƽỏƾǦǉƽƙǂǦǃƼườƾǦǃữƶǦ——",
    ["你别问了！哪个数字最小，我就信哪个！"] = "ĐệǦđừǃƼǦƽỏƾǦǃữƶ!ǦƮốǦǃƐǄǦǃƽỏǦǃƽấǉǦǉƽƔǦǉƶǦǉƾǃǦǈốǦđƚ!",
    ["还爬吗？"] = "ƞƛǃǦǁƺǄǦǃữƶǦǀƽƇǃƼ?",
    ["你还爬吗？"] = "ƩƼươƾǦƸƛǃǦǁƺǄǦǀƽƇǃƼ?",
    ["我先问的，你还爬吗？"] = "ǥƶǦƽỏƾǦǉǇướƸǦǂƐ,ǦǃƼươƾǦƸƛǃǦǁƺǄǦǀƽƇǃƼ?",
    ["你爬我就爬。"] = "ƩƼươƾǦǁƺǄǦǉƽƔǦǉƶǦǁƺǄ.",
    ["你爬我也爬。"] = "ƩƼươƾǦǁƺǄǦǉƶǦƸũǃƼǦǁƺǄ.",
    ["我还行。"] = "ǥƶǦǋẫǃǦổǃ.",
    ["我没说不行。"] = "ǥƶǦđƁǊǦƸƚǦǃƚƾǦǁƐǦǀƽƇǃƼǦđượƸ.",
    ["那还爬吗？"] = "ǥƽếǦƸƛǃǦǁƺǄǦǀƽƇǃƼ?",
    ["前面就是南天门了！看见光了没有！"] = "ƫƽƓƶǦǉǇướƸǦƸƽƓǃƽǦǁƐǦƩƶǂǦǥƽƾƙǃǦƨƇǃǦǇồƾ!ǦǥƽấǓǦƑǃƽǦǈƑǃƼǦƸƽưƶ!",
    ["水呢？我记得带了两壶的……"] = "ƩướƸǦđƁǊǦǇồƾ?ǦǥƶǦǃƽớǦǁƐǦƸƚǦǂƶǃƼǦǉƽƺǄǦƽƶƾǦƷƔǃƽǦǂƐ……",
    ["早知道该买两块糖糕垫垫的……"] = "ƝƾếǉǦǉƽếǦǃƃǓǦǂǊƶǦƽƶƾǦǂƾếǃƼǦƷƑǃƽǦđườǃƼǦăǃǦǁƚǉǦǤạǦƸƽǄǦǇồƾ……",
    ["刚才路过那卖绿豆汤的，我该买一碗的……"] = "ƧƕƸǦǃƃǓǦđƾǦǃƼƶǃƼǦƸƽỗǦƷƑǃǦƸƶǃƽǦđậǊǦǍƶǃƽ,ǦđƑǃƼǦǁẽǦǉƶǦǃƙǃǦǂǊƶǦǂộǉǦƷƑǉ……",
    ["来来来，划个五行拳！谁输谁下山买吃食去！"] = "ǥớƾǦǁǊƇǃǦǉớƾǦǁǊƇǃ,ǦǄẳǃǦǉƖǦǉƔǦƩƼũǦƣƐǃƽǦƬǊǓềǃǦđƾ!ǦƜƾǦǉƽǊƶǦǃƼườƾǦđƚǦǍǊốǃƼǦǃƕƾǦǂǊƶǦđồǦăǃ!",
    ["三、二、一！"] = "Ɲƶ,Ǧƽƶƾ,Ǧǂộǉ!",
    ["王淼，你输了！下去买糖糕和绿豆汤去！"] = "ƱươǃƼǦƨƾểǊ,ǦǃƼươƾǦǉƽǊƶǦǇồƾ!ǦƳǊốǃƼǦǂǊƶǦƷƑǃƽǦđườǃƼǦǋớƾǦƸƶǃƽǦđậǊǦǍƶǃƽǦđƾ!",
    ["不对不对！刚才我没准备好，重来！"] = "ƦƽƇǃƼǦđƕǃƼǦǀƽƇǃƼǦđƕǃƼ!ǦƩƃǓǦǉƶǦƸƽưƶǦƸƽǊẩǃǦƷịǦǍǄǃƼ,ǦǁƐǂǦǁạƾ!",
    ["哎哎哎，哪有耍赖的？"] = "ÊǦƙǦƙ,ǦƶƾǦǁạƾǦƸƽơƾǦăǃǦƼƾƶǃǦǉƽếǦƽả?",
    ["阿团兄，你抬头看看，南天门就在那儿了，"] = "ƜǦĐǄƐǃǦƽǊǓǃƽ,ǦƽǊǓǃƽǦǃƼẩǃƼǦđầǊǦǁƙǃǦǃƽƔǃǦǍƺǂ,ǦƩƶǂǦǥƽƾƙǃǦƨƇǃǦởǦǃƼƶǓǦǀƾƶǦǇồƾ,",
    ["撑过这几步就，到了山顶，给你买两只鸡腿，成不成？"] = "ƞốǦǃốǉǦǂấǓǦƷướƸǦǃƐǓǦǉƽƇƾ,ǦǁƙǃǦǉớƾǦđỉǃƽǦǃƕƾǦǉƶǦǂǊƶǦƸƽǄǦƽǊǓǃƽǦƽƶƾǦƸƑƾǦđƖƾǦƼƐ,ǦƸƽịǊǦǀƽƇǃƼ?",
    ["三只……五只！不能再多了！"] = "ƝƶǦƸƑƾ……ǦƩăǂǦƸƑƾ!ǦƦƽƇǃƼǦǉƽểǦǃƽƾềǊǦƽơǃǦđượƸǦǃữƶǦđƁǊ!",
    ["还没到？南天门不就在前面了吗？"] = "ƱẫǃǦƸƽưƶǦǉớƾǦǈƶǄ?ǦƩƶǂǦǥƽƾƙǃǦƨƇǃǦƸƽẳǃƼǦǅƽảƾǦởǦǃƼƶǓǦǅƽƓƶǦǉǇướƸǦǇồƾǦƐ?",
    ["可不就在眼前嘛。阿团偏生这时候撂挑子了，几步路都不肯走。"] = "ƞƽẳǃƼǦǅƽảƾǦǃƼƶǓǦǉǇướƸǦǂắǉǦđƚǦǈƶǄ.ǦƞƑƾǦǉƙǃǦƜǦĐǄƐǃǦǃƐǓǦǉựǦǤưǃƼǦǤởǦƸƽứǃƼǦđƛƾǦƷỏǦƼƑǃƽ,ǦƸƚǦǂấǓǦƷướƸǦƸƽƁǃǦǂƐǦƸũǃƼǦǀƽƇǃƼǦƸƽịǊǦđƾ.",
    ["唉，我再劝劝它……它估计是嫌我把它从家"] = "ƣƶƾǏ,ǦđểǦǉƶǦǀƽǊǓƙǃǦǃƚǦǉƽƙǂǦƸƽƕǉǦǃữƶ……ǦƞƽắƸǦǁƐǦǃƚǦǤỗƾǦǋƔǦǉƶǦǁƇƾǦǃƚǦǉừǦǃƽƐ",
    ["里拖出来受这份罪，哄好了，兴许就肯走了。"] = "ƭƶǦđƁǓǦƸƽịǊǦǀƽổǦǉƽếǦǃƐǓ,ǦǤỗǦǤƐǃƽǦǍǄǃƼǦƸƽắƸǦǁƐǦǃƚǦƸƽịǊǦđƾǦǉƽƇƾ.",
    ["青州老乡们共同写给游侠的一封信："] = "ƧƑǦǉƽưǦƸủƶǦǃƽữǃƼǦǃƼườƾǦđồǃƼǦƽươǃƼǦǥƽƶǃƽǦƞƽƁǊǦƼửƾǦƸƽǄǦǝǊǦƣƾệǅ:",
    ["游侠！听说你清河来的，那咱就是正经乡亲啊！清河吃把子肉，我们青州人也好这一口把子肉，光冲这口肉，咱就绝不是外人！既不是外人，你大老远跑来青州，我们咋能不表示表示？\n\n琢磨来琢磨去，也没啥拿得出手的宝贝，就一块儿给你做了这本手账！小杨夫子说这东西在别处也有类似的，有个雅得很的名，叫嘉时录！我们参考着他描述的功用，额外加了几页，给它起了个名叫青州游山记。\n\n你路上看见啥好景、遇见啥好玩的事儿，都往里头记。走累了翻翻，还能想起咱青州的风、青州的土，还有我们这帮絮絮叨叨的老乡！"] = "ǝǊǦƽƾệǅ!ǦƩƼƽƺǦǃƚƾǦǃƼươƾǦǉừǦǥƽƶǃƽǦƣƐǦǉớƾ,ǦǉƽếǦǉƽƔǦđƕǃƼǦǁƐǦđồǃƼǦƽươǃƼǦƸƽƓǃƽǦƽƾệǊǦǇồƾ!ǦǥƽƶǃƽǦƣƐǦƸƚǦǂƚǃǦǉƽịǉǦǀƽǄǦǉƐǊǦ(ƷảǦǉửǦǃƽụƸ),ǦǤƁǃǦǥƽƶǃƽǦƞƽƁǊǦǉụƾǦǉƶǦƸũǃƼǦǂƙǦǂƚǃǦđƚǦǁắǂ,ǦƸƽỉǦǇƾƙǃƼǦƸƑƾǦǂƚǃǦǉƽịǉǦđƚǦǉƽƇƾǦǁƐǦđủǦǉƽấǓǦǉụƾǦǂƔǃƽǦǀƽƇǃƼǦǅƽảƾǦǃƼườƾǦǃƼǄƐƾǦǇồƾ!ǦĐƃǦǀƽƇǃƼǦǅƽảƾǦǃƼườƾǦǃƼǄƐƾ,ǦǃƼươƾǦǁạƾǦǁặǃǦǁộƾǦđườǃƼǦǍƶǦǉớƾǦǥƽƶǃƽǦƞƽƁǊ,ǦǉụƾǦǉƶǦǈƶǄǦƸƚǦǉƽểǦǀƽƇǃƼǦƸƚǦƸƽƕǉǦǆǊƐǦƸƑǅǦƷƾểǊǦƈǦƸƽứ?\n\nǥƓǃƽǦđƾǦǉƓǃƽǦǁạƾǦƸũǃƼǦƸƽẳǃƼǦƸƚǦƷƑǊǦǋậǉǦƼƔǦđƑǃƼǦƼƾƑ,ǦǃƙǃǦǉụƾǦǉƶǦƸƖǃƼǦǃƽƶǊǦǁƐǂǦƸƽǄǦǃƼươƾǦƸǊốǃǦǈổǦǉƶǓǦǃƐǓ!ǦǥƾểǊǦǝươǃƼǦǅƽǊǦǉửǦǃƚƾǦǉƽứǦǃƐǓǦởǦǃƽữǃƼǦǃơƾǦǀƽƑƸǦƸũǃƼǦƸƚǦƸƑƾǦǉươǃƼǦǉự,ǦƸƚǦƸƑƾǦǉƙǃǦǇấǉǦǃƽƃǦǁƐǦƢƾƶǦǥƽờƾǦƧụƸ!ǦǥụƾǦǉƶǦǤựƶǦǉƽƺǄǦƸƇǃƼǦǤụǃƼǦǂƐǦǅƽǊǦǉửǦǂƇǦǉả,ǦǉƽƙǂǦǋƐǄǦǋƐƾǦǉǇƶǃƼǦǃữƶ,ǦđặǉǦǉƙǃǦƸƽǄǦǃƚǦǁƐǦǥƽƶǃƽǦƞƽƁǊǦǝǊǦƮơǃǦƦƈ.\n\nǥǇƙǃǦđườǃƼǦđƾǦǉƽấǓǦƸảǃƽǦđẹǅǦƼƔ,ǦƼặǅǦƸƽǊǓệǃǦƼƔǦƽƶǓǦƽǄ,ǦǃƼươƾǦƸứǦƼƽƾǦƽếǉǦǋƐǄǦđƁǓ.ǦĐƾǦǂỏƾǦƸƽƁǃǦǉƽƔǦǁƇƾǦǇƶǦǁậǉǦǍƺǂ,ǦđểǦƸƛǃǦǃƽớǦǉớƾǦƼƾƚǦǥƽƶǃƽǦƞƽƁǊ,ǦđấǉǦǥƽƶǃƽǦƞƽƁǊ,ǦǋƐǦƸảǦđƑǂǦđồǃƼǦƽươǃƼǦƽƶǓǦǁảƾǦǃƽảƾǦǉụƾǦǉƶǦǃữƶǦǃƽƗ!",
    ["青州老乡"] = "ĐồǃƼǦƽươǃƼǦǥƽƶǃƽǦƞƽƁǊ",
    ["哈……你说今天备这些料，够不够？"] = "ƣƐ……ǦƩƼươƾǦǍƺǂǦƸƽǊẩǃǦƷịǦƷấǓǦǃƽƾƙǊǦǃƼǊǓƙǃǦǁƾệǊǦƸƽǄǦƽƇǂǦǃƶǓǦǁƾệǊǦƸƚǦđủǦǀƽƇǃƼ?",
    ["杜素素"] = "ĐỗǦǥốǦǥố",
    ["反正昨天茶汤都没够，今天可要多煮些！"] = "ǝƖǦǈƶǄǦƽƇǂǦǆǊƶǦǃướƸǦǉǇƐǦƸũǃƼǦǀƽƇǃƼǦđủǦƷƑǃ,ǦƽƇǂǦǃƶǓǦǅƽảƾǦǃấǊǦǃƽƾềǊǦǉƽƙǂǦƸƽƕǉ!",
