    ["修研值"] = "ĐƾểǂǦǉǊǦǃƼƽƾƙǃ",
    ["探索青州，可提升研修值，解锁更多生徒行簿中的奖励。"] = "ƦƽƑǂǦǅƽƑǦǥƽƶǃƽǦƞƽƁǊǦƸƚǦǉƽểǦǉăǃƼǦđƾểǂǦǉǊǦǃƼƽƾƙǃ,ǦǂởǦǀƽƚƶǦǉƽƙǂǦǃƽƾềǊǦǅƽầǃǦǉƽưởǃƼǦǉǇǄǃƼǦƮƾǃƽǦĐồǦƣƐǃƽǦƝạ.",
    ["助挑夫一肩之力，共陟高冈"] = "ƢƾƕǅǦǅƽǊǦƼƑǃƽǦǂộǉǦǋƶƾ,ǦƸƖǃƼǦǋượǉǦƼƛǦƸƶǄ",
    ["赶集除秽，不避脏累"] = "ĐƾǦƸƽợǦǉǇừǦǊế,ǦƸƽẳǃƼǦǆǊảǃǦƷẩǃǦǂệǉ",
    ["路遇翻车，尽数扶助"] = "ĐườǃƼǦƼặǅǦǍƺǦǁậǉ,ǦƽếǉǦǁƛǃƼǦǉươǃƼǦǉǇợ",
    ["研习丝竹，余音绕梁"] = "ƩƼƽƾƙǃǦǉậǅǦǉơǦǉǇƕƸ,ǦǤưǦƁǂǦǋƶǃƼǦǋọǃƼ",
    ["尽愈病患，悬壶乡里"] = "ƞƽữƶǦǈạƸƽǦƷệǃƽǦǉậǉ,ǦƽƐǃƽǦǓǦƼƾƕǅǦđờƾ",
    ["口若悬河，话术无双"] = "ƨƾệǃƼǦǁưỡƾǦǁƾǃƽǦƽǄạǉ,ǦǉƽǊậǉǦǃƼữǦǋƇǦǈǄǃƼ",
    ["肃净匪患，靖守乡梓"] = "ǝẹǅǦǈạƸƽǦƼƾặƸǦƼƾƃ,ǦƼƔǃǦƼƾữǦǍƚǂǦǁƐǃƼ",
    ["育葱中魁首，独步葱王坪"] = "ǥǇồǃƼǦƽƐǃƽǦǆǊƑǃǦǆǊƁǃ,ǦđộƸǦƸƽƾếǂǦǥƽƇǃƼǦƱươǃƼǦƝƔǃƽ",
    ["赶集丰收，满载而归"] = "ĐƾǦƸƽợǦƷộƾǦǉƽǊ,ǦǆǊƐǦƸƑǅǦđầǓǦƼƾỏ",
    ["援手与蟹，尽数解救"] = "ƢƾƕǅǦđỡǦǁǄƐƾǦƸǊƶ,ǦƼƾảƾǦƸứǊǦǉấǉǦǉƽảǓ",
    ["初习礼让，情礼之始"] = "ƨớƾǦǉậǅǦǁễǦǃƽượǃƼ,ǦǀƽởƾǦđầǊǦǉƔǃƽǦǁễ",
    ["初逢乡人，交游以启"] = "ƨớƾǦƼặǅǦǃƼườƾǦǁƐǃƼ,ǦƷắǉǦđầǊǦƼƾƶǄǦǤǊ",
