    ["九十一"] = "ƞƽƓǃǦǂươƾǦǂốǉ",
    ["月下白"] = "ƩƼǊǓệǉǦƣạǦƝạƸƽ",
    ["八十五"] = "ǥƑǂǦǂươƾǦǁăǂ",
    ["八十七"] = "ǥƑǂǦǂươƾǦƷảǓ",
    ["八十六"] = "ǥƑǂǦǂươƾǦǈƑǊ",
